"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { REQUESTS, type WaitingRequest } from "./selection-toolbar/data";
import { SelectionBar } from "./selection-toolbar/selection-bar";

const UNDO_MS = 6000;

/** What the last batch action did, so it can be undone. */
interface LastAction {
  word: string;
  removed: WaitingRequest[];
}

const plural = (count: number) => `${count} request${count === 1 ? "" : "s"}`;

/**
 * A waiting list with a checkbox on every request. While anything is
 * selected, a bar rises under the list with the count and the batch actions.
 * Archive and Delete remove the rows at once and offer Undo for a few
 * seconds. Escape clears the selection.
 */
export function SelectionToolbar({ className }: { className?: string }) {
  const titleId = useId();
  const [rows, setRows] = useState(REQUESTS);
  const [selected, setSelected] = useState<Set<string>>(() => new Set(["r1", "r3"]));
  const [last, setLast] = useState<LastAction | null>(null);
  const [notice, setNotice] = useState("");
  const undoTimer = useRef<number | null>(null);

  useEffect(
    () => () => {
      if (undoTimer.current !== null) window.clearTimeout(undoTimer.current);
    },
    [],
  );

  const count = selected.size;
  const all = rows.length > 0 && count === rows.length;

  const toggle = (id: string, on: boolean) => {
    setNotice("");
    setSelected((current) => {
      const next = new Set(current);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  };

  const clear = () => setSelected(new Set());

  const remove = (word: string) => {
    const removed = rows.filter((row) => selected.has(row.id));
    setRows((current) => current.filter((row) => !selected.has(row.id)));
    clear();
    setLast({ word, removed });
    setNotice(`${plural(removed.length)} ${word}.`);
    if (undoTimer.current !== null) window.clearTimeout(undoTimer.current);
    undoTimer.current = window.setTimeout(() => setLast(null), UNDO_MS);
  };

  const undo = () => {
    if (!last) return;
    const back = new Set(last.removed.map((row) => row.id));
    setRows(REQUESTS.filter((row) => back.has(row.id) || rows.some((kept) => kept.id === row.id)));
    setNotice(`${plural(last.removed.length)} restored.`);
    setLast(null);
  };

  const offer = () => {
    setNotice(`Slot offers sent to ${plural(count)}.`);
    clear();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape" && count > 0) {
      event.preventDefault();
      clear();
    }
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div onKeyDown={onKeyDown} className="relative">
        <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
          <div>
            <h2 id={titleId} className="text-base font-semibold">
              Waiting list
            </h2>
            <p className="text-sm text-muted-foreground">{plural(rows.length)} for an earlier slot</p>
          </div>
          {last ? (
            <p className="flex items-center gap-2 text-sm text-muted-foreground">
              {plural(last.removed.length)} {last.word}
              <Button type="button" variant="outline" size="sm" onClick={undo}>
                Undo
              </Button>
            </p>
          ) : null}
        </header>

        <label className="flex min-h-11 cursor-pointer items-center gap-3 border-b border-border px-5 text-sm text-muted-foreground">
          <Checkbox
            checked={all ? true : count > 0 ? "indeterminate" : false}
            onCheckedChange={(value) => setSelected(value === true ? new Set(rows.map((row) => row.id)) : new Set())}
            aria-label="Select every request"
            disabled={rows.length === 0}
          />
          {count > 0 ? `${count} of ${rows.length}` : "Select all"}
        </label>

        <ul aria-label="Requests" className="flex flex-col gap-0.5 p-2 pb-24">
          {rows.length === 0 ? <li className="px-3 py-8 text-center text-sm text-muted-foreground">The waiting list is empty.</li> : null}
          {rows.map((row) => {
            const checked = selected.has(row.id);
            return (
              <li key={row.id}>
                <label className="group relative isolate flex cursor-pointer items-center gap-3 rounded-lg px-3 py-2.5 has-focus-visible:ring-2 has-focus-visible:ring-ring">
                  <span
                    aria-hidden="true"
                    className={cn("absolute inset-0 -z-10 rounded-lg", checked ? "bg-muted" : "group-hover:bg-muted/50")}
                  />
                  <Checkbox checked={checked} onCheckedChange={(value) => toggle(row.id, value === true)} aria-label={`Select ${row.patient}`} />
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span className="truncate text-sm font-medium">{row.patient}</span>
                    <span className="truncate text-xs text-muted-foreground">
                      {row.visit} with {row.practitioner}, {row.clinic}
                    </span>
                  </span>
                  {row.urgent ? (
                    <span className={cn("hidden rounded-full px-2 py-0.5 text-xs font-medium @sm:inline", STATUS_SURFACE.bad, STATUS_TEXT.bad)}>Urgent</span>
                  ) : null}
                  <span className="w-14 shrink-0 text-right text-xs text-muted-foreground tabular-nums">{row.waited}</span>
                </label>
              </li>
            );
          })}
        </ul>

        <div className="pointer-events-none absolute inset-x-0 bottom-4 flex justify-center px-3">
          <SelectionBar count={count} onOffer={offer} onArchive={() => remove("archived")} onDelete={() => remove("deleted")} onClear={clear} />
        </div>
      </div>
      <p aria-live="polite" className="sr-only">
        {notice || (count > 0 ? `${plural(count)} selected.` : "")}
      </p>
    </BlockFrame>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** One patient waiting for an earlier slot. */
export interface WaitingRequest {
  id: string;
  patient: string;
  visit: string;
  practitioner: string;
  clinic: string;
  /** How long the patient has waited, already written. */
  waited: string;
  urgent: boolean;
}

/** The waiting list a front desk works through. Every name is invented. */
export const REQUESTS: WaitingRequest[] = [
  { id: "r1", patient: "Amara Okafor", visit: "Physiotherapy follow-up", practitioner: "Dr Lena Brandt", clinic: "Harbour Street", waited: "9 days", urgent: true },
  { id: "r2", patient: "Tomasz Wiśniewski", visit: "Hearing test", practitioner: "Priya Raman", clinic: "Mill Lane", waited: "6 days", urgent: false },
  { id: "r3", patient: "Hana Sato", visit: "Child vaccination", practitioner: "Dr Owen Price", clinic: "Northgate", waited: "5 days", urgent: true },
  { id: "r4", patient: "Diego Alvarez", visit: "Dental check", practitioner: "Dr Mia Laurent", clinic: "The Quay", waited: "4 days", urgent: false },
  { id: "r5", patient: "Freya Lindqvist", visit: "Blood test", practitioner: "Nurse Sam Cole", clinic: "Harbour Street", waited: "3 days", urgent: false },
  { id: "r6", patient: "Kwame Mensah", visit: "Knee review", practitioner: "Dr Lena Brandt", clinic: "Orchard Road", waited: "3 days", urgent: false },
  { id: "r7", patient: "Isla Mackenzie", visit: "Skin check", practitioner: "Dr Ravi Shah", clinic: "Mill Lane", waited: "2 days", urgent: true },
