"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";

import { CheckIcon, TrashIcon, XIcon } from "../../parts/icons";
import { ArchiveIcon } from "../icons";

/** Props for the floating selection bar. */
export interface SelectionBarProps {
  count: number;
  onOffer: () => void;
  onArchive: () => void;
  onDelete: () => void;
  onClear: () => void;
}

// Critically damped rise: the bar arrives quickly and settles without a bounce.
const RISE: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
// Leaving is faster than arriving, because the person has already moved on.
const SINK: Transition = { duration: 0.14, ease: [0.4, 0, 1, 1] };
const FADE: Transition = { duration: 0.15 };
const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/**
 * A bar that rises under the list while anything is selected. It names the
 * count, offers the batch actions and clears the selection. The count rolls,
 * the plural ending fades in place, and the width springs, so the actions do
 * not jump. Reduced motion keeps only the fades.
 */
export function SelectionBar({ count, onOffer, onArchive, onDelete, onClear }: SelectionBarProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence>
      {count > 0 ? (
        <motion.div
          key="bar"
          role="toolbar"
          aria-label="Selected requests"
          layout={!reduceMotion}
          initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 16, scale: 0.94 }}
          animate={reduceMotion ? { opacity: 1, transition: FADE } : { opacity: 1, y: 0, scale: 1, transition: RISE }}
          exit={reduceMotion ? { opacity: 0, transition: FADE } : { opacity: 0, y: 12, scale: 0.96, transition: SINK }}
          transition={RISE}
          className="pointer-events-auto flex max-w-full items-center gap-1 rounded-full border border-border bg-popover p-1.5 pl-4 text-popover-foreground shadow-lg backdrop-blur-md"
        >
          <motion.span layout={reduceMotion ? false : "position"} className="mr-2 flex items-baseline text-sm font-medium whitespace-nowrap">
            <NumberTicker value={count} format={WHOLE} />
            &nbsp;request
            <motion.span initial={false} animate={{ opacity: count === 1 ? 0 : 1 }} transition={FADE} aria-hidden={count === 1}>
              s
            </motion.span>
            &nbsp;selected
          </motion.span>
          <Button type="button" variant="ghost" size="sm" onClick={onOffer}>
            <CheckIcon aria-hidden="true" />
            <span className="hidden @md:inline">Offer slot</span>
            <span className="sr-only @md:hidden">Offer slot</span>
          </Button>
          <Button type="button" variant="ghost" size="sm" onClick={onArchive}>
            <ArchiveIcon aria-hidden="true" />
            <span className="hidden @md:inline">Archive</span>
            <span className="sr-only @md:hidden">Archive</span>
          </Button>
          <Button type="button" variant="ghost" size="sm" onClick={onDelete}>
            <TrashIcon aria-hidden="true" />
            <span className="hidden @md:inline">Delete</span>
            <span className="sr-only @md:hidden">Delete</span>
          </Button>
          <span aria-hidden="true" className="mx-1 h-5 w-px bg-border" />
          <Button type="button" variant="ghost" size="icon" aria-label="Clear selection" onClick={onClear} className="size-8">
            <XIcon aria-hidden="true" />
          </Button>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

